package com.tneff.cyppie.evm

import kotlin.test.Test
import kotlin.test.assertEquals

/**
 * KAN-154/KAN-159 — byte-exact pin of the EntryPoint v0.7 userOpHash recompute against the backend's
 * deterministic enable-userOp KAT (`Backend/aa-trigger/scripts/enable-userop-vector.mjs` @e7ea914): the real
 * install(SmartSessions)+enableSessions callData with fixed gas/nonce. The app raw-signs `digestToSign =
 * hashMessage(userOpHash)`; recomputing the hash on-device (and asserting equality before signing) is what
 * binds the owner's (root-validator, full-authority) signature to the verified op — no blind-signing a drain.
 */
class Erc4337UserOpTest {

    // Fixed envelope fields (same on both chains; the canonical vector's deterministic part).
    private val sender = "0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266"
    private val nonce = "0x0"
    private val initCode = "0x"
    private val accountGasLimits = "0x0000000000000000000000000016e360000000000000000000000000000927c0"
    private val preVerificationGas = "0x30d40"
    private val gasFees = "0x0000000000000000000000003b9aca000000000000000000000000003b9aca00"
    private val paymasterAndData = "0x0000000000000039cd5e8aE05257CE51C473ddd100000000000000000000000000061a80000000000000000000000000000186a0"

    private fun op(callData: String) = Erc4337UserOp.PackedUserOp(
        sender = sender, nonce = nonce, initCode = initCode, callData = callData,
        accountGasLimits = accountGasLimits, preVerificationGas = preVerificationGas,
        gasFees = gasFees, paymasterAndData = paymasterAndData,
    )

    @Test
    fun userOpHashAndDigest_chain1() {
        val hash = Erc4337UserOp.userOpHash(op(CALLDATA_ETH), chainId = 1L)
        assertEquals("c4d1510e7efadce1ca010db75fe501d2ae685f14b8c27c4fe364ed1d0170dfe9", Hex.encode(hash))
        assertEquals(
            "e7d07e62aba236625113c51e2c9b24b7cda6ff8d23157f3ae9f9d793e1e4e118",
            Hex.encode(Erc4337UserOp.digestToSign(hash)),
        )
    }

    @Test
    fun userOpHashAndDigest_base() {
        val hash = Erc4337UserOp.userOpHash(op(CALLDATA_BASE), chainId = 8453L)
        assertEquals("7fa6707b20e07e1ed55c1fa9f4eb5893efb46497b8f007c198b28ea6a928c194", Hex.encode(hash))
        assertEquals(
            "1af0767764637fc2ba38cae9b0a72a85951ac1d1a952ead6dd58f23e2105c415",
            Hex.encode(Erc4337UserOp.digestToSign(hash)),
        )
    }

    @Test
    fun entryPointIsCanonicalV07() {
        assertEquals("0x0000000071727De22E5E9d8BAf0edAc6f37da032", Erc4337UserOp.ENTRY_POINT_V07)
    }

    @Test
    fun decodesEnableBatch_installThenEnableSessions() {
        // Structure asserts (KAN-154/159): the enable op is EXACTLY install(SmartSessions) + enableSessions.
        // NB resolved vs the contract prose ("both to=sender"): exec[1].to is the SmartSessions MODULE, not the follower.
        val execs = KernelExecuteBatch.decodeBatch(CALLDATA_ETH)
        assertEquals(2, execs.size)
        assertEquals("0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266", execs[0].target) // install on the follower SCA (self)
        assertEquals("0x9517e29f", KernelExecuteBatch.selectorOf(execs[0]))         // installModule(uint256,address,bytes)
        assertEquals("0x00000000008bDABA73cD9815d79069c247Eb4bDA", execs[1].target) // enableSessions on the SmartSessions module
    }

    private companion object {
        const val CALLDATA_ETH = ""
        const val CALLDATA_BASE = ""
    }
}
